        action('↖︎ Smaller',()=>{const t=subbyLanternFitCurrent();subbyLanternFitSet({ScaleX:Math.max(.3,t.ScaleX-.1),ScaleY:Math.max(.3,t.ScaleY-.1)},{updateUi:false});});
        action('Bigger ↗︎',()=>{const t=subbyLanternFitCurrent();subbyLanternFitSet({ScaleX:Math.min(2.5,t.ScaleX+.1),ScaleY:Math.min(2.5,t.ScaleY+.1)},{updateUi:false});});
