            const C=window.Player;const candidates=[C?.CanvasResize,C?.CanvasBlink,C?.Canvas,C?.DrawCanvas,C?.CanvasCharacter,C?.CanvasFull];
            let img=null;for(const a of candidates){for(const value of (Array.isArray(a)?a:[a])){if(value?.width>=120&&value?.height>=250&&typeof value.getContext==='function'){img=value;break;}}if(img)break;}
            if(img){try{ctx.drawImage(img,0,img.height>1500?600:0,img.width,img.height>1500?Math.min(1000,img.height-600):img.height,0,0,210,420);}catch(_){ }}
            const t=subbyLanternFitCurrent();
