    function subbyLanternQueueRpText(text) {
        const input=document.getElementById('InputChat') || document.querySelector('#InputChat, textarea[id="InputChat"], input[id="InputChat"]');
        if (input) {
            const existing=String(input.value || '');
            input.value = existing ? `${existing}${existing.endsWith(' ') ? '' : ' '}${text}` : text;
            try{input.dispatchEvent(new Event('input',{bubbles:true}));}catch(_){ }
            try{input.focus();}catch(_){ }
            appendLocalInfoBox('Heartkeeper Lantern', ['RP line inserted into chat input.']);
            return true;
        }
        try{navigator.clipboard?.writeText?.(text);}catch(_){ }
        appendLocalInfoBox('Heartkeeper Lantern', ['Could not reach the chat box, so the RP line was copied (or attempted to copy) instead:', text]);
        return false;
    }
