    const EXTENSIONS_FIND_GROUPS = Object.freeze(['All','Plushies','Clothing & tools','Chat & social','Safety & poses','Performance','Appearance & layout','Progress & help']);
    function extensionsNavigate(item) {
        if (!item) return false;
        extensionsMobileMoreOpen = false;
        if (item.action) {
            if (item.action === 'time-machine') return openOutfitTimeMachineFromExtensions();
            if (item.action === 'plushie-picker') return mobilePlushBrowser();
            if (item.action === 'mascot') return openRoomMascotPicker();
            if (item.action === 'emoticons') return window.SubbysEssentialsExtras?.emoticons?.();
            if (item.action === 'color-studio') return window.SubbysEssentialsExtras?.colorStudio?.();
            if (item.action === 'moodboards') return window.PawAestheticMoodboards?.open('essentials');
            if (item.action === 'custom-items') return plushieItemsBrowser?.open?.();
            if (item.action === 'harmonizer') {
                try { return (window.SubbysOutfitHarmonizer || installSmartOutfitColorHarmonizer())?.open?.(); }
                catch(e) { warn('Outfit Harmonizer unavailable:',e); return false; }
            }
            return false;
        }
        extensionsActiveTab = item.tab || 'status';
        if (extensionsActiveTab === 'settings') extensionsSettingsTab = item.sub || 'general';
        else if (extensionsActiveTab === 'progress') extensionsProgressTab = item.sub || 'stats';
        else if (extensionsActiveTab === 'chatstyles') extensionsChatStudioTab = item.sub || 'public';
        if (item.details) extensionsShowStatusDetails = true;
        renderExtensionsPanel();
        if (extensionsPanelContent) extensionsPanelContent.scrollTop = 0;
        if (item.section) window.requestAnimationFrame(() => {
            const content=extensionsPanelContent;
            if (!content?.isConnected || extensionsActiveTab !== item.tab) return;
            const title=[...content.querySelectorAll('section > h2,section > h3')]
                .find(el=>el.textContent.trim().toLowerCase().includes(item.section.toLowerCase()));
            if (title) content.scrollTop += title.getBoundingClientRect().top - content.getBoundingClientRect().top - 8;
        });
        return true;
    }
    function extensionsFindResults(query, category) {
        const words=String(query||'').trim().toLocaleLowerCase().split(/\s+/).filter(Boolean);
        const ranked=EXTENSIONS_FIND_ITEMS.filter(item=>category==='All'||item.group===category).map((item,index)=>{
            const text=[item.name,item.summary,item.tags,item.group].join(' ').toLocaleLowerCase();
            if (!words.every(word=>text.includes(word))) return null;
            const title=item.name.toLocaleLowerCase();
            return {item,index,rank:!words.length?index:(title.startsWith(words[0])?0:title.includes(words[0])?1:2)};
        }).filter(Boolean);
        return ranked.sort((a,b)=>a.rank-b.rank||a.index-b.index).map(entry=>entry.item);
    }
