            summary.textContent=showingPopular
                ? `Popular destinations · Search or choose a category to browse all ${EXTENSIONS_FIND_ITEMS.length} features.`
                : `${matches.length} ${matches.length===1?'feature':'features'} found${extensionsFindCategory==='All'?'':' in '+extensionsFindCategory}`;
