            const rect=root.getBoundingClientRect();
            const availableW=Math.max(190,vp.left+vp.width-rect.left-6);
            const availableH=Math.max(220,vp.top+vp.height-rect.top-6);
            const w=Math.min(availableW,Math.max(Math.min(290,availableW),gesture.w+e.clientX-gesture.x));
            const h=Math.min(availableH,Math.max(Math.min(260,availableH),gesture.h+e.clientY-gesture.y));
            root.style.width=Math.round(w)+'px';root.style.height=Math.round(h)+'px';
            root.dataset.bookCompact=(mobileEssentialMode()||w<720||h<580)?'true':'false';
            root.dataset.catShort=h<555?'true':'false';
            root.style.setProperty('--subbys-cat-header-px',Math.round(h*0.265)+'px');
            root.style.setProperty('--subbys-cat-footer-px',Math.round(Math.min(70,Math.max(40,h*0.073)))+'px');
            e.preventDefault();
