    function essentialsRenderXRay(section) {
        const character=window.Player;
        const worn=(Array.isArray(character?.Appearance)?character.Appearance:[]).filter(item=>item?.Asset?.Group?.Category==='Appearance'&&item.Asset.Group.Clothing);
        const chosen=new Set();
        section.append(essentialsH('p','Choose visible clothing layers to hide in a private preview. No changes are applied or sent to the room.',{color:getExtensionsStyle().muted,fontSize:'12px'}));
        const choices=essentialsH('div',null,{maxHeight:'165px',overflowY:'auto',display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(170px,1fr))',gap:'6px'});
        for(const item of worn){
            const group=item.Asset.Group.Name;
            const line=essentialsH('label',null,{display:'flex',alignItems:'center',gap:'6px',fontSize:'12px'});
            const check=document.createElement('input');check.type='checkbox';check.addEventListener('change',()=>{if(check.checked)chosen.add(group);else chosen.delete(group);});
            line.append(check,document.createTextNode(String(item.Asset.Group.Description||group)+' · '+String(item.Asset.Name)));
            choices.append(line);
        }
        section.append(choices);
        const output=essentialsH('div',null,{marginTop:'10px',minHeight:'32px'});
        const btn=essentialsBtn('Preview hidden layers',()=>{
            output.replaceChildren();
            const api=window.__BCOutfitTimeMachine;
            if(!api?.xrayPreview){output.textContent='Time Machine preview renderer is not available.';return;}
            btn.disabled=true;
            try{
                const url=api.xrayPreview([...chosen]);
                if(url&&/^data:image\/(png|jpeg|webp);base64,/.test(url)){
                    const img=document.createElement('img');img.src=url;img.alt='Private X-Ray outfit preview';
                    Object.assign(img.style,{display:'block',width:'min(280px,100%)',height:'min(420px,55vh)',objectFit:'contain',background:'#14101b',borderRadius:'8px'});
                    output.append(img);
                }else output.textContent='Preview unavailable with the current BC/Echo renderer. Your outfit was not modified.';
            }catch(e){output.textContent='Could not render this outfit privately.';}
            finally{btn.disabled=false;}
        });
        section.append(btn,output);
        if(!worn.length)section.append(essentialsH('p','No worn clothing layers were detected.'));
    }

