        // the Tools popup outside that clipped strip, within the same panel.
        if (root.dataset.subbysCat !== 'true') {
            const popup = root.querySelector('.SubbysCatQuickLinks');
            const launcher = tabs.querySelector('.SubbysCatToolsTrigger');
            if (popup && launcher) {
                root.append(popup);
                const positionTools = () => {
                    const panelRect = root.getBoundingClientRect();
                    const buttonRect = launcher.getBoundingClientRect();
                    popup.style.top = `${Math.round(Math.max(0,buttonRect.bottom-panelRect.top+5))}px`;
                    popup.style.right = `${Math.round(Math.max(6,panelRect.right-buttonRect.right))}px`;
                    popup.style.maxHeight = `${Math.round(Math.max(85,panelRect.bottom-buttonRect.bottom-14))}px`;
                };
                launcher.addEventListener('click',positionTools);
            }
        }
        installExtensionsResponsiveHook();
        extensionsPanelElement = root;
        extensionsPanelContent = content;
