            if(settings.textAtMentions&&content.includes('@')){
                if(!names){names=textFxAliasesInRoom();own=new Set(textFxAliases(window.Player).map(x=>x.toLocaleLowerCase()));}
                textFxMarkAtMentions(row,names,own);
            }
