        dialog.append(el('p','muted',`Choose which pieces of “${entry.label||'Outfit'}” to apply. Preview and confirm before making any changes.`));
        const groups=[['clothing','Clothing (including Echo slots)'],['accessories','Accessories'],['hair','Hair'],['body','Body and face'],['colors','Saved colors'],['settings','Saved positioning / item settings']];
        const options={clothing:true,accessories:true,hair:false,body:false,colors:true,settings:true};
        const choices=el('div','restore-choices');dialog.append(choices);
