            if(e.button!==0)return;
            e.preventDefault();e.stopPropagation();
            gesture={id:e.pointerId,startX:e.clientX,startY:e.clientY,left:parseFloat(b.style.left)||0,top:parseFloat(b.style.top)||0,moved:false};
