  const state = {emotes:[], catalogSource:'builtin', modal:null, section:'colors', searchText:'', paletteIndex:0, itemGroup:'', swatchIndex:0, chatLog:null, logObserver:null, catalogError:'', message:'', chatButton:null, selectedGroups:new Set(), colorUndo:null};
