  function recolorable(item){
    if(essentialsRecolorProtectedSlot(item) || isOutfitProtected(item))return false;
    const group=item?.Asset?.Group;
    if(group?.Category!=='Appearance' || (!group.Clothing && !WARDROBE_ITEM_NAME_SET.has(item.Asset?.Name)))return false;
    if(item?.Property?.LockedBy||item?.Property?.LockMemberNumber!=null||item?.Property?.Effect?.includes?.('Lock'))return false;
    return true;
  }
  function applyColors(multi,batch=false){
    const player=window.Player,palette=currentPalette(),appearance=availableItems();
    if(!player)return refreshColorsStatus('Player not loaded.');
    if(typeof player.CanChange==='function'&&!player.CanChange())return refreshColorsStatus('BC currently restricts changing your appearance.');
    const list=appearance.filter(x=>batch?state.selectedGroups.has(x.group):x.group===state.itemGroup);
    if(!list.length)return refreshColorsStatus(batch?'Check at least one clothing item.':'Select an equipped clothing item first.');
    const changes=[];let skipped=0;
    try{
      for(const found of list){
        const item=found.item;if(!recolorable(item)){skipped++;continue;}
        const nativeZones=WARDROBE_ITEMS.find(entry=>entry.name===item.Asset?.Name)?.colorZones?.length;
        const count=Math.min(12,Math.max(1,Number(nativeZones)||Number(item.Asset?.ColorableLayerCount)|| (Array.isArray(item.Color)?item.Color.length:1)));
        const colors=Array.from({length:count},(_,i)=>multi?palette.swatches[i%palette.swatches.length]:palette.swatches[state.swatchIndex]);
        changes.push({group:found.group,itemName:item.Asset.Name,old:Array.isArray(item.Color)?[...item.Color]:item.Color});
        // Assign colors to native appearance items, using one redraw + network update after the batch.
        item.Color=Array.isArray(item.Color)?colors:colors[0];
      }
      if(!changes.length)return refreshColorsStatus('All selected items were locked or not changeable.');
      for(const changed of changes){
        if(WARDROBE_ITEM_NAME_SET.has(changed.itemName)){
          const item=player.Appearance?.find(x=>x?.Asset?.Name===changed.itemName&&x?.Asset?.Group?.Name===changed.group);
          if(item)wardrobeRememberColors(changed.itemName,Array.isArray(item.Color)?item.Color:[item.Color]);
        }
      }
      appearanceShieldAllowEssentials("Essentials Color Studio");
      window.CharacterRefresh?.(player,false,false);
      window.CharacterLoadCanvas?.(player);
      if(window.CurrentScreen==='ChatRoom')window.ChatRoomCharacterUpdate?.(player);
      else window.ServerPlayerAppearanceSync?.();
      state.colorUndo={member:player.MemberNumber,changes};
      refreshColorsStatus(`Recolored ${changes.length} clothing item(s)${skipped?`; skipped ${skipped} locked item(s)`:''}. Undo available until next recoloring.`);
    }catch(e){
      // Roll back the locally changed colors rather than leaving a partially modified outfit.
      for(const entry of changes){const cur=player.Appearance?.find(item=>item?.Asset?.Name===entry.itemName&&item?.Asset?.Group?.Name===entry.group);if(cur)cur.Color=entry.old;}
      try{window.CharacterRefresh?.(player,false,false);window.CharacterLoadCanvas?.(player);}catch(_){}
      refreshColorsStatus(`Could not apply colors: ${e?.message||e}. Local colors restored.`);
    }
  }
  function undoColorOperation(){
    const undo=state.colorUndo,player=window.Player;
    if(!undo||!player||player.MemberNumber!==undo.member)return refreshColorsStatus('Nothing to undo in this session.');
    if(typeof player.CanChange==='function'&&!player.CanChange())return refreshColorsStatus('BC currently restricts changing your appearance.');
    let count=0;
    for(const old of undo.changes){
      const item=player.Appearance?.find(x=>x?.Asset?.Name===old.itemName&&x?.Asset?.Group?.Name===old.group);
      if(item&&recolorable(item)){item.Color=Array.isArray(old.old)?[...old.old]:old.old;count++;}
    }
    appearanceShieldAllowEssentials('Essentials Color Studio Undo');
    try{window.CharacterRefresh?.(player,false,false);window.CharacterLoadCanvas?.(player);
      if(window.CurrentScreen==='ChatRoom')window.ChatRoomCharacterUpdate?.(player);
      else window.ServerPlayerAppearanceSync?.();
      state.colorUndo=null;refreshColorsStatus(`Restored ${count} item(s).`);
    }catch(e){refreshColorsStatus(`Undo could not synchronize: ${e?.message||e}`);}
  }
